      ['把线擦了，第二天还过界', { cha: 5, amb: 4, happy: -2 }, '你们推搡了一场，被老师一起罚站。站着的时候他偷偷递给你半块糖。这条线后来再没画过。'],
      ['一句话不说，把桌子往回挪了十公分', { int: 4, amb: 3, cha: -2 }, '你宁可自己挤在边上，也不肯越线。他愣了半天，第二天把桌子挪回去了。你学会了一种不出声的办法。']
