      ['跟着车跑了一段', { cha: 4, happy: 3, health: -2 }, '你跑了大概一百米，车拐弯了。你站在路口喘气，手里还攥着他给的那颗润喉糖。'],
      ['站着没动，看他上车', { int: 3, happy: -2, con: 2 }, '车开了，你敬了个不太标准的礼。他隔着玻璃摆了摆手。你后来再没见过他。'],
      ['把联系方式要过来', { cha: 5, happy: 4 }, '他写在你的本子上，字很难看。你加了他微信，头两年还聊几句，后来就只剩朋友圈点赞。']
