      ['笑着应下这个外号', { cha: 5, happy: 2 }, '你自己先说"钢牙来了"，别人反而不好意思再叫。两年后摘掉牙套那天，你在镜子前笑了很久。'],
      ['尽量不笑', { happy: -4, cha: -3, int: 2 }, '你捂了两年嘴。毕业照上你也是抿着嘴的。你后来看那张照片，觉得那不像自己。'],
      ['跟医生说能不能换成隐形', { cha: 4, family: -2, money: -3 }, '母亲算了算价钱，说太贵。你没再提。但你记住了那个数字，也记住了自己开口时的犹豫。']
