      ['认真报出数字', { con: 3, happy: -2, cha: 2 }, '你报得很平静。有女生说"你挺高的"。你才知道，一米六八在这个班不算矮。'],
      ['回家开始跳绳、摸高、喝牛奶', { con: 5, health: 3, happy: 1 }, '你练了一年，长了两厘米。你不知道是练的还是本来就要长，但你一直觉得那一年的牛奶没白喝。']
