      ['故意大声说，破了也接着说', { cha: 6, amb: 4, happy: 3 }, '破音了三次，笑了三次，第四次就不破了。你后来在班上朗读课文，老师说你声音好听。'],
      ['找没人的地方练', { int: 4, con: 4, happy: 2 }, '你每天早上在厕所里念十分钟课文。一个星期后你自己听出来了变化。这事谁都不知道。']
