      ['借了两千，分十二期', { money: -3, happy: 4, int: 2 }, '你还了一年，利息四百。你按时还完了，但那一年你每个月都在算钱。'],
      ['借了，还不上，又借了另一个', { money: -6, happy: -6, health: -3 }, '你滚到八千，最后跟家里说了。父亲转账时没说话，只发了一句"以后别碰"。']
