      ['不做了，太丢人', { happy: -3, money: -2, amb: -3 }, '你把设备转手了。后来你在写字楼里加班到十点，偶尔会想起校门口那两个月。'],
      ['去办个正经的摊位证', { cha: 6, int: 5, amb: 5 }, '你跑了两周，办下来了。有了证就不怕查。你们做到了毕业，最后转给了学弟。']
