      ['第二天再来，走进去了', { health: 5, happy: 6, cha: 4 }, '你聊了六次，哭过两次。咨询师说你没有病，只是很久没跟人说过真话。'],
      ['一直没进去', { happy: -5, health: -3, int: 2 }, '你在门外站了两次。毕业时那张表还在你的文件夹里。'],
      ['改成跟一个朋友说', { cha: 5, family: 4, happy: 5 }, '你跟一个朋友聊了一夜。她听完说"我也是"。你们后来成了彼此的安全出口。']
