      ['故意做鬼脸', { cha: 6, happy: 5 }, '全班就你一个鬼脸。多年后同学群里还拿那张照片开玩笑。'],
      ['站在最后一排，不太想被看见', { happy: -2, int: 3 }, '你站在最后排的边上，只露出半张脸。你后来翻到这张照片，会先看别人。']
