      ['找同事聊两句，撑过去', { cha: 5, happy: 4, health: -2 }, '你们在护士站聊了半小时。她说她上了十年夜班。你后来跟她学了很多。'],
      ['申请换班，说身体不行', { cha: 5, health: 4, money: -2 }, '护士长给你调了。有同事说你事多。但你确实撑不住。']
