      ['让伴侣去说', { cha: 5, family: 3, happy: 2 }, '伴侣去说了，说得不太好，两边都有点不痛快。但调料回到了原来的位置。'],
      ['自己开口，说想按自己的习惯来', { cha: 6, amb: 4, family: -3, happy: 3 }, '你说得很客气。她愣了一下，说"那你们自己弄"。第二天她买了一套新调料，放在新的位置。']
