      ['一家一半，除夕在这边初一在那边', { con: 4, cha: 4, family: 3, health: -2 }, '你们大年三十吃了两顿年夜饭，跑了四百公里。累得够呛，但两边都满意。'],
      ['各回各家，各找各妈', { cha: 5, int: 4, family: -3, happy: 4 }, '你们分开过的年。亲戚问起来有点尴尬，但你那年过得最轻松。后来就成了惯例。']
