      ['不送，只把活干好', { con: 4, int: 3, happy: 2 }, '你没送。那两年你的绩效一直中规中矩。你说这样睡得踏实。'],
      ['送点家乡的土特产，不贵', { cha: 6, int: 4, happy: 3 }, '你送了两袋自家晒的干货，说是家里寄来的。领导很高兴，还问怎么做。']
