      ['起来工作，反正睡不着', { amb: 4, health: -5, happy: -3 }, '你干脆四点开始干活。半年后你的作息彻底乱了，白天像在梦游。'],
      ['去看睡眠门诊', { health: 5, money: -3, happy: 4 }, '医生给你做了睡眠监测，是焦虑导致的早醒。治了半年，好了。']
