  add('fishing', 5, 34, '一整天没鱼',
    '你三十四岁，跟伴侣的父亲去钓鱼。坐了六个小时，一条没上。',
    [
      ['继续坐着，陪他把话说完', { family: 6, happy: 4, con: 4 }, '他说了很多年轻时候的事。你后来才知道，那天他是故意带你去的。'],
      ['换位置、换饵，折腾', { int: 3, happy: 2, family: 2 }, '你换了三次位置。他还是没动。最后他钓上来一条，你比他还高兴。'],
      ['提前收竿，去买了两条', { cha: 5, happy: 3, family: 3 }, '你从菜场买了两条回去，说是在下游钓的。他看了一眼，笑了，没拆穿。']
    ], { cond: s => hasPartner(s) })

  add('volunteer', 5, 31, '周末的那四个小时',
    '你三十一岁，公司组织去福利院做志愿者。周六上午，本来想睡懒觉。',
    [
      ['去了，认真陪了一上午', { cha: 5, happy: 6, family: 3 }, '你陪一个老人下了三盘棋，他每盘都输，但每次都笑。你后来每个月都去。'],
      ['签个到就走', { cha: 3, happy: -2, amb: -2 }, '你待了二十分钟，拍了张合照就出来了。你在商场里逛了一下午。'],
      ['不去，把名额让给别人', { happy: 2, int: 2 }, '你没去。后来看了同事发的照片，那个老人坐在轮椅上，手里拿着一个纸折的船。']
    ])

  add('donate', 5, 30, '那笔捐款',
    '你三十岁，看到一条求助信息，一个孩子的手术费差八万。你手里有三万闲钱。',
    [
      ['捐一万', { money: -4, happy: 6, family: 3 }, '你捐了一万，没留名字。半年后你收到一条回复，说孩子手术成功了。你把那条消息存了下来。'],
      ['先查证再捐', { int: 6, cha: 4, money: -2 }, '你查了三天，联系上了医院。确认是真的，你捐了五千。你说谨慎不是冷漠。'],
      ['不捐，怕是骗的', { happy: -2, int: 3 }, '你没捐。后来那条信息被证实是真的。你有点难受，但也说不清自己该不该。']
    ])

  add('breakup_30', 5, 31, '三十二岁那年分手',
    '你三十一岁，谈了三年的对象说要分开。理由是"我们不合适"，说得很平静。',
    [
      ['问清楚哪里不合适', { cha: 5, happy: -5, int: 4 }, '他/她说了三条，每条你都能反驳，但你没反驳。你听完说"我知道了"。'],
      ['什么都不问，收拾东西', { con: 4, happy: -7 }, '你三天搬完。最后一趟你把钥匙放在桌上，回头看了一眼那间屋子。'],
      ['求一次，说可以改', { cha: 4, happy: -6, amb: -3 }, '你说你改。他/她摇头。半年后你才承认，有些事不是改不改的问题。']
    ], { cond: s => !hasPartner(s) })

  add('blind_date_30', 5, 30, '第七次相亲',
    '你三十岁，第七次相亲。对方条件都合适，坐下第一句话是"你有房吗"。',
    [
      ['照实说，有贷款', { con: 4, cha: 4, happy: 2 }, '她点点头，说"我也有"。你们后来聊了两个小时，聊得挺好。第二次没约成。'],
      ['反问"你有吗"', { cha: 6, amb: 4, happy: 3 }, '她愣了一下，笑了，说"你这人挺有意思"。你们成了朋友，她后来给你介绍了一个人。'],
      ['说没有，然后不再说话', { happy: -3, cha: -3 }, '那顿饭吃了四十分钟。走的时候你们都说"再联系"。你删了她的微信。']
    ], { cond: s => !hasPartner(s) })

  add('move_back_home', 5, 30, '搬回父母家',
    '你三十岁，房租涨了，工资没涨。母亲说"回来住吧，省点钱"。',
    [
      ['搬回去，存两年钱', { money: 4, family: 3, happy: -3, cha: -2 }, '你搬回去了，存了十二万。但你也失去了很多自由。两年后你搬出去，觉得像逃出来的。'],
      ['不搬，宁可住远一点', { con: 4, money: -2, happy: 4, amb: 3 }, '你搬到了郊区，房租省一半。每天多坐半小时地铁。你说这种自由值这个价。'],
      ['搬回去，但定好规矩', { cha: 6, int: 5, family: 5 }, '你跟父母约法三章：不问工作、不催婚、不随便进房间。他们答应了。你住了三年。']
    ])

  add('body_check', 5, 35, '三十五岁那年的体检',
    '你三十五岁，体检报告上有七个箭头。医生看完说"该管管了"。',
    [
      ['认真改一年', { con: 6, health: 7, happy: 4 }, '你戒了夜宵，每周运动三次，一年后五个箭头没了。你说这是给自己的三十五岁礼物。'],
      ['看一眼，收起来', { happy: 2, health: -4 }, '你把报告放进抽屉。四十岁那年你住了院。'],
      ['只挑最严重的一项改', { int: 5, con: 4, health: 4 }, '你只改了血脂。一年后那项正常了。你说一次改一样，比什么都改更容易坚持。']
    ])

  /* ============================================================
   *  stage 6 · 三十六到五十五岁（上有老下有小）
   * ============================================================ */

  add('kid_gaokao', 6, 43, '孩子高考的前一晚',
    '你四十三岁，孩子明天高考。你在客厅坐着，电视开着没声音，你也睡不着。',
    [
      ['去敲他的门，说两句', { family: 5, cha: 4, happy: 3 }, '你敲门进去，说"考完就行，别想别的"。他"嗯"了一声。你出来发现他灯关了。'],
      ['坐在客厅等到一点', { con: 4, family: 3, happy: -3, health: -3 }, '你等到他房间彻底没光。第二天早上你熬了粥，他吃了两碗。'],
      ['自己进屋睡了，什么都不做', { int: 3, happy: 2 }, '你回房躺着，也没睡着。第二天送考，你在校门口站了一上午。']
    ], { cond: s => hasKid(s) })

  add('kid_major', 6, 43, '孩子要报的那个专业',
    '你四十三岁，孩子填志愿，非要报一个你觉得没前途的专业。他/她说"我就要这个"。',
    [
      ['让他自己选，签个字', { family: 4, happy: 4, cha: 4 }, '他填了。你后来偷偷查过那个专业的就业率。四年后他找的工作跟专业有关，做得还行。'],
      ['吵一场，最后他妥协了', { family: -6, happy: -4, amb: 3 }, '他报了另一个专业，大学四年学得很敷衍。你后来一直觉得这件事有你的责任。'],
      ['跟他一起研究，看看到底是什么', { int: 6, family: 6, happy: 5 }, '你花了一个星期看了很多资料。你发现那个专业比你想象的窄，也比他想象的难。最后是你们一起定的。']
    ], { cond: s => hasKid(s) })

  add('kid_abroad', 6, 45, '那张录取通知',
    '你四十五岁，孩子拿到国外学校的录取，一年四十万。',
    [
      ['砸锅卖铁送出去', { money: -9, family: 5, happy: 4, amb: 4 }, '你卖了第二套房。孩子出去了，读完留下工作。你们一年见一次，视频里他瘦了。'],
      ['不送，国内读也一样', { family: -4, money: 3, happy: 2 }, '他留在国内。后来他偶尔说起同学在国外，语气平淡。你不知道他有没有怪过你。'],
      ['让他自己申请奖学金', { cha: 5, int: 6, family: 4 }, '他申了两年，拿到半奖。你出了一半的钱。他出去以后比谁都知道省。']
    ], { cond: s => hasKid(s) })

  add('kid_marry', 6, 48, '孩子带回来一个人',
    '你四十八岁，孩子带对象回家吃饭。你端详了一整晚，觉得不太合适。',
    [
      ['什么都不说，好好招待', { family: 5, cha: 6, happy: 3 }, '你做了一桌菜。他们走后孩子问你"你觉得怎么样"，你说"你自己看"。孩子说"我觉得挺好"。'],
      ['当面提了几个问题', { cha: 5, family: -4, happy: -2 }, '你问了工作和家庭。气氛有点僵。孩子后来跟你说"你让我很没面子"。'],
      ['私下跟孩子聊一次', { cha: 6, family: 4, happy: 4 }, '你说"我不喜欢的是某一点，不是这个人"。孩子听完说"我再看看"。半年后他们分手了。']
    ], { cond: s => hasKid(s) })

  add('in_law_meet', 6, 50, '亲家第一次见面',
    '你五十岁，孩子结婚前双方家长见面。对方家里比你们有钱，说话有点往上。',
    [
      ['客气着，把场面撑住', { cha: 6, happy: 2, family: 3 }, '你笑着应了一晚。回来路上你老伴说"他们看不起人"，你说"孩子喜欢就行"。'],
      ['该说的话说清楚', { cha: 5, amb: 4, family: 3 }, '你说彩礼、房子、以后怎么过，一条条摊开。对方反而认真起来了。'],
      ['中途借口出门抽了根烟', { happy: -2, cha: -2 }, '你在饭店门口站了很久。回去的时候他们已经聊到婚礼酒店了。']
    ], { cond: s => hasKid(s) })

  add('grandchild_first', 6, 52, '第一次抱孙子',
    '你五十二岁，孩子生了。护士把那个包着的小东西递给你，你手都在抖。',
    [
      ['抱紧，眼眶就热了', { happy: 9, family: 7 }, '你抱了五分钟，谁要都不给。你说这孩子眉眼像他爸小时候。'],
      ['站在原地，不敢接', { cha: 3, happy: 5, family: 4 }, '你说"我手重"。护士笑着教你托住头。你后来抱得比谁都稳。'],
      ['先去洗手，洗了三遍', { con: 4, happy: 6, family: 4 }, '你洗得特别认真。回来的时候孩子醒了，看着你。你说那一刻什么都值了。']
    ], { cond: s => hasKid(s) })

  add('parent_dementia', 6, 50, '妈不认得你了',
    '你五十岁，母亲开始忘事。今天她看着你，问"你是谁家的孩子"。',
    [
      ['一次次告诉她"我是你儿子/女儿"', { family: 5, happy: -6, con: 4 }, '她每次都点头，然后就忘。你重复了几百遍。有一天她突然叫对了你的名字，你在厨房哭了。'],
      ['顺着她的话说', { cha: 4, family: 4, happy: -3 }, '你说"我是来看您的"。她很高兴，给你拿了水果。那种假装，你后来做得很熟练。'],
      ['带她去医院', { health: 3, family: 3, money: -3, happy: -3 }, '确诊了阿尔茨海默。医生说只能延缓。你开始学着怎么跟一个慢慢消失的人相处。']
    ])

  add('parent_helpless', 6, 48, '换尿布的那天',
    '你四十八岁，父亲卧床。今天第一次给他换尿布，他一直说"别，别"。',
    [
      ['什么都不说，把他翻过来', { con: 5, family: 5, happy: -4 }, '你做完，洗了手，在卫生间站了一会儿。他后来不再说了，只是每次闭着眼。'],
      ['叫护工来，自己出去', { money: -2, family: -2, happy: -5 }, '你在门外听见他在跟护工道谢。你靠着墙，觉得心里有块东西塌了。'],
      ['跟他说"小时候你也给我换过"', { cha: 5, family: 7, happy: 3 }, '他愣了一下，笑了，眼睛红了。那天以后他配合多了。']
    ])

  add('sibling_quarrel', 6, 47, '谁出这个钱',
    '你四十七岁，母亲住院。你哥/姐说"你条件好，你多出点"。',
    [
      ['出了，什么都不说', { money: -5, family: 2, happy: -3 }, '你出了大半。这件事你记着，但没提。后来分家产时你没争。'],
      ['把账摊开算', { cha: 5, int: 5, family: -5, money: 2 }, '你列了一张表，按月分摊。他/她脸色很难看，但签了。你们的关系从此公事公办。'],
      ['先垫，等母亲好了再说', { int: 4, family: 4, money: -3 }, '你先垫了。母亲出院后你把账单发在家庭群里，没人回。你也没再问。']
    ])

  add('empty_nest_real', 6, 50, '孩子搬走后的第一个月',
    '你五十岁，孩子搬出去住。房间收拾干净了，门开着，里面空的。',
    [
      ['把房间改成书房', { int: 5, happy: 4, family: 3 }, '你收拾了三天，扔了两箱东西。后来你每天在那间屋里看书，看得很安心。'],
      ['什么都不动，保持原样', { family: 3, happy: -5 }, '床铺好了，书还在书架上。你每周进去擦一次灰。三年后你才把床拆了。'],
      ['打电话让他回来吃饭', { family: 5, cha: 4, happy: 4 }, '他每周回来一次。你开始学着做他爱吃的菜，做得比以前好。']
    ], { cond: s => hasKid(s) })

  add('marriage_flat', 6, 45, '分房睡的第三年',
    '你四十五岁，和伴侣分房三年。白天正常说话，晚上各进各屋。',
    [
      ['找一次机会，认真谈', { cha: 6, family: 6, happy: 4 }, '你们聊了一整夜。有些话说开了，有些还是没法说。但你们搬回了一间屋。'],
      ['就这样吧，习惯了', { happy: -4, family: -3, con: 3 }, '你们这样过了十几年。孩子结婚那天，你们并排站着，像一对很好的夫妻。'],
      ['各自找点寄托', { happy: 2, family: -4, int: 3 }, '你开始学画画，他/她开始跳广场舞。你们互不干涉，也互不过问。']
    ], { cond: s => hasPartner(s) })

  add('career_out', 6, 45, '四十岁的简历',
    '你四十五岁，被裁。投了三个月简历，面试两次。HR 说"我们想找个更年轻的"。',
    [
      ['降薪去小公司', { money: -4, happy: 2, con: 4 }, '你去了家小公司，工资少了四成，但活不累。你在那儿干到退休。'],
      ['自己干，接活', { amb: 6, cha: 5, money: -2, health: -3 }, '你注册了个小公司，一个人接项目。第一年赔，第二年平，第三年比上班挣得多。'],
      ['考证转行', { int: 6, con: 5, money: -3, happy: 3 }, '你考了个证，去了一个不卡年龄的行业。工资回到原来的七成，但你觉得踏实。']
    ])

  add('industry_gone', 6, 46, '整个行业没了',
    '你四十六岁，做了二十年的行业在萎缩。公司一年裁三次，同行都在转行。',
    [
      ['转行，从头学', { int: 6, amb: 5, money: -3, happy: 3 }, '你花了两年学新东西。四十多岁跟二十几岁的人一起上课，很难，但你学下来了。'],
      ['守着，等它慢慢死', { con: 4, happy: -4, money: -3 }, '你守到最后，公司关了。你拿了赔偿，那年五十岁。'],
      ['把老本行做成小生意', { cha: 6, amb: 5, money: 2, happy: 4 }, '你用二十年的人脉接私活，做成了一个小工作室。收入不如从前，但自由。']
    ])

  add('tech_replaced', 6, 48, '新系统上线',
    '你四十八岁，公司上了新系统。二十几岁的同事两天就上手，你学了一个月还会出错。',
    [
      ['下班留下来练', { con: 6, int: 5, happy: 2 }, '你练了一个月，记了三本笔记。后来你成了组里最会用这个系统的人。'],
      ['找年轻人教', { cha: 5, int: 4, happy: 4 }, '你请一个刚来的小姑娘教你，还请她喝了奶茶。她说"您学得比我爸快"。'],
      ['能糊弄就糊弄，等退休', { happy: 2, amb: -5, money: -2 }, '你混了两年，被调去做边缘的活。工资没降，但你知道自己已经被放在了边上。']
    ])

  add('young_boss', 6, 47, '新来的领导比你小十岁',
    '你四十七岁，部门换了领导，三十七岁。他开会时说"有些老办法要改"。',
    [
      ['配合，把经验给他', { cha: 6, int: 5, happy: 3 }, '你主动找他聊了两次，把坑都说了。他后来什么事都先问你。你说这叫识时务。'],
      ['不服，当面顶', { amb: 5, cha: 3, family: -4, happy: -3 }, '你在会上顶了他一次。之后半年你手上没有重要项目。'],
      ['申请调去别的组', { cha: 5, int: 4, happy: 2 }, '你调走了。新组的老大跟你同岁。你在那儿待到了退休。']
    ])

  add('invest_boom', 6, 44, '那个稳赚的项目',
    '你四十四岁，朋友介绍一个项目，年化十五，说得头头是道。你手里有六十万。',
    [
      ['投三十万试水', { money: -6, happy: -6, int: 4 }, '前半年真返了。你追加了三十万。第三个月公司跑了。你报了案，钱没了。'],
      ['不投，问他要合同和牌照', { int: 6, cha: 5, happy: 2 }, '他拿不出来。你拒绝了。一年后那个项目暴雷，你的朋友赔了两百万。'],
      ['投一点，就当交学费', { money: -2, happy: -2, int: 5 }, '你投了五万，亏光了。你说这五万买了个教训，值。']
    ])

  add('scam_call', 6, 50, '安全账户',
    '你五十岁，接到电话说你涉嫌洗钱，要转到"安全账户"。对方说出了你的身份证号。',
    [
      ['挂了，打 110 核实', { int: 5, cha: 3, money: 2, happy: 3 }, '警察说这是典型诈骗。你把号码举报了。后来你在小区群里讲了一遍。'],
      ['慌了，按他说的做', { money: -9, happy: -7, family: -3 }, '你转了十八万。反应过来时已经晚了。你在派出所做了三个小时笔录。'],
      ['跟对方周旋，套信息', { cha: 6, int: 5, happy: 4 }, '你聊了四十分钟，套出了他们的窝点信息。警察说很少见到这么冷静的。']
    ])

  add('health_product', 6, 52, '那场讲座',
    '你五十二岁，社区有个免费健康讲座，去了送鸡蛋。讲到一半开始卖保健品，一万二一套。',
    [
      ['买了，说对身体好', { money: -6, happy: 3, health: -2 }, '你吃了半年，没什么感觉。孩子回来看到盒子，跟你吵了一架。你后来自己停了。'],
      ['不买，拿了鸡蛋就走', { cha: 4, int: 4, happy: 2 }, '你走的时候推销的人脸色很难看。你在楼下碰见两个邻居，跟他们说了。'],
      ['当场拆穿他们', { cha: 6, amb: 4, happy: 4 }, '你问他们要批号，他们答不上来。现场走了大半人。社区后来取消了这类活动。']
    ])

  add('surgery', 6, 48, '手术同意书',
    '你四十八岁，要做个手术，医生说了三种风险。签字的地方在你手上。',
    [
      ['仔细问，问完再签', { int: 6, cha: 4, health: 4, happy: 2 }, '你问了二十分钟，医生讲得很细。你签了。手术顺利。'],
      ['直接签，不想听太多', { happy: 1, health: 2, int: -2 }, '你签得很快。术后有点并发症，你又住了五天。'],
      ['把家属都叫来一起听', { family: 6, cha: 4, health: 3 }, '你们四个人一起听的。后来你老伴说，幸好当时听清了。']
    ])

  add('recover', 6, 49, '康复科的第三个月',
    '你四十九岁，手术后在康复科。每天练抬腿，一天两次，一次二十分钟。',
    [
      ['一天不落，认真练', { con: 7, health: 7, happy: 3 }, '你练了半年，能自己走路了。医生说你这个年纪恢复成这样不容易。'],
      ['疼就停，慢慢来', { health: -3, con: 2, happy: 2 }, '你练练停停，恢复得慢。一年后还有点跛。'],
      ['偷偷加练', { con: 6, health: -2, happy: 3 }, '你多练了一倍，结果拉伤了，又多躺了三周。']
    ])

  add('knee', 6, 50, '上下楼梯的时候',
    '你五十岁，膝盖开始疼。蹲下去要扶一下，站起来要缓两秒。',
    [
      ['去查，听医生的', { health: 4, money: -2, happy: 2 }, '医生说是退行性改变，让你减重、别爬楼。你搬到了一楼。'],
      ['忍着，少走路', { health: -4, happy: -3, con: 2 }, '你越不动越疼。两年后连买菜都费劲。'],
      ['练肌肉，把膝盖保住', { con: 6, health: 6, happy: 4 }, '你练了半年大腿肌肉，疼得少了。医生说这比吃药有用。']
    ])

  add('menopause', 6, 50, '那阵热潮',
    '你五十岁，突然一阵热从胸口上来，脸红，出汗。一天十几次。',
    [
      ['去看医生，做激素治疗', { health: 5, money: -2, happy: 4 }, '医生评估后给你开了药。三个月后好多了。你说早知道就早点来。'],
      ['忍着，听说会过去', { con: 5, health: -3, happy: -4 }, '你忍了两年，睡眠很差，脾气也变了。后来自己慢慢好了。'],
      ['调整作息和运动', { con: 5, health: 4, happy: 3 }, '你开始游泳，戒了咖啡。症状轻了一些，人也精神了。']
    ])

  add('kid_depressed', 6, 45, '孩子关上的门',
    '你四十五岁，孩子半年不怎么出房间。成绩掉了很多，问他什么都说"没事"。',
    [
      ['带他去看医生', { health: 5, family: 6, money: -3, happy: -2 }, '确诊中度抑郁。你请了三个月假陪他。你说那三个月是你人生最难的三个月。'],
      ['觉得是叛逆，骂了一顿', { family: -7, happy: -6 }, '他摔了门。之后一个月没跟你说话。你后来才知道他那时候在想什么。'],
      ['不追问，只是每天陪他吃顿饭', { family: 5, cha: 4, happy: 3 }, '你什么都不问，就每天做他爱吃的。三个月后他自己开口了。']
    ], { cond: s => hasKid(s) })

  add('kid_game', 6, 42, '凌晨三点的游戏声',
    '你四十二岁，凌晨三点起来喝水，孩子房间还亮着，键盘在响。',
    [
      ['推门进去，把电脑关了', { cha: 4, family: -5, happy: -3 }, '你们吵了一架。他把门反锁了。第二天你把网断了，他一周没跟你说话。'],
      ['坐下来，看他玩一会儿', { cha: 6, family: 5, happy: 4 }, '你看了二十分钟，问了几句。他讲得很起劲。你们后来定了个时间表，他自己守。'],
      ['什么都不说，回去睡', { happy: -2, family: -2, int: 2 }, '你回房躺着。这件事持续了两年，成绩掉了两百名。']
    ], { cond: s => hasKid(s) })

  add('kid_money_steal', 6, 40, '少了的三百块',
    '你四十岁，钱包里少了三百。家里只有三个人。',
    [
      ['直接问孩子', { cha: 4, family: -3, happy: -3 }, '他否认。你翻了他的书包，找到了两盒卡片。他哭了。你后来跟他聊了很久。'],
      ['不问了，把钱放好', { int: 3, family: 2, happy: -2 }, '你把钱包收进了抽屉。之后没再少过。你一直不知道是不是他。'],
      ['跟伴侣商量，一起观察', { cha: 5, family: 4, int: 4 }, '你们观察了一个月，发现是孩子。你们一起找他谈，没骂，只问了为什么。']
    ], { cond: s => hasKid(s) })

  add('kid_love', 6, 42, '孩子的手机屏保',
    '你四十二岁，看见孩子手机屏保是一张合照，跟一个同学，靠得很近。',
    [
      ['什么都不说，装作没看见', { cha: 4, family: 2, happy: 1 }, '你什么都没说。半年后他自己跟你提了，说"你别生气"。'],
      ['找个机会聊两句', { cha: 6, family: 5, happy: 4 }, '你说"喜欢一个人很正常，但别耽误自己"。他说"我知道"。你们聊得挺好。'],
      ['直接说不行，学业要紧', { family: -5, happy: -3, amb: 2 }, '他不说话了，把屏保换了。你知道他还在联系，只是不让你看见。']
    ], { cond: s => hasKid(s) })

  add('kid_no_school', 6, 44, '不想去上学的早上',
    '你四十四岁，孩子早上赖在床上，说"我不想去学校了"。这已经是这周第三次。',
    [
      ['硬拉起来，送去', { con: 4, family: -4, happy: -3 }, '他一路没说话。到校门口他站了一会儿才进去。你开车走的时候手在抖。'],
      ['请假一天，问到底怎么了', { cha: 6, family: 6, happy: 3 }, '你们在家聊了一整天。他说被老师针对。你后来去学校谈了一次。'],
      ['先请一周假，带他出去走走', { cha: 5, family: 5, money: -2, happy: 4 }, '你们去了趟外地。回来后他自己说要去上学。你不知道是哪句话起了作用。']
    ], { cond: s => hasKid(s) })

  add('care_elder_choice', 6, 46, '养老院的那张宣传单',
    '你四十六岁，父母年纪大了，一个人在家不安全。养老院一个月六千。',
    [
      ['送养老院', { money: -5, family: -3, happy: -4 }, '你去看了三次才定下。送进去那天你妈抓着你的手不放。你每周去两次。'],
      ['请住家保姆', { money: -4, family: 3, happy: 2 }, '保姆换了三个。第四个很细心，一直做到老人走。你给她包了个大红包。'],
      ['接到自己家', { family: 6, money: -2, happy: 2, health: -3 }, '你把老人接过来了。三年里你没出过远门。你说这是应该的，也说不出别的。']
    ])

  add('friends_die', 6, 50, '第一个走的同学',
    '你五十岁，同学群里发了一条消息：某某走了。心梗，四十九岁。',
    [
      ['去参加葬礼', { family: 3, cha: 3, happy: -5 }, '你去了。遗像上的他还是大学那张照片。回来的路上你给几个老朋友打了电话。'],
      ['在群里发了一句"节哀"', { cha: 2, happy: -4, int: 3 }, '你发完就退出了。那天晚上你翻了自己的体检报告。'],
      ['一个人去喝了一场酒', { happy: -3, health: -2, int: 4 }, '你坐在小馆子里喝到十一点。老板问你要不要加个菜，你说不用。']
    ])

  add('first_love_again', 6, 46, '那条好友申请',
    '你四十六岁，微信弹出一条好友申请，是初恋。附言只有一句"好久不见"。',
    [
      ['通过了，聊几句', { cha: 5, happy: 5, family: -3 }, '你们聊了两个小时，都是过去的事。后来偶尔点赞。你说这挺好的。'],
      ['不通过', { con: 4, happy: -2, family: 2 }, '你点了忽略。那天晚上你想了很多，第二天就忘了。'],
      ['通过了，然后约了见面', { cha: 6, happy: 4, family: -6 }, '你们见了一面，喝了咖啡。她胖了，头发短了。你们聊了一个小时，各自回家。']
    ])

  add('old_friend_back', 6, 45, '二十年没见的人',
    '你四十五岁，出差到另一个城市，想起一个二十年没见的老朋友。',
    [
      ['打个电话，约出来', { cha: 6, happy: 7, family: 3 }, '他半小时就到了。你们聊到饭店打烊。他说"你还是那个样"。'],
      ['发了条消息，没约', { cha: 4, happy: 2, int: 2 }, '他回了"下次一定"。你们都说了下次，也都知道下次是什么时候。'],
      ['什么都没做，走了', { happy: -3, int: 3 }, '你在酒店里翻了他的朋友圈，翻到三年前。第二天你上了飞机。']
    ])

  add('wedding_kid_old', 6, 50, '孩子的婚礼上',
    '你五十岁，孩子结婚。台上司仪让你说两句，话筒递到你手上。',
    [
      ['说几句场面话', { cha: 5, family: 3, happy: 4 }, '你说了三句，都是谢谢。下台后你老伴说"你说得太短了"。'],
      ['讲了一件他小时候的事', { cha: 6, family: 6, happy: 7 }, '你讲他五岁走丢那次。台下都笑了，孩子红了眼睛。'],
      ['一句都说不出来，把话筒递回去', { happy: 3, family: 5, cha: -2 }, '你站在那儿，摆了摆手。全场鼓掌。你回到座位上，喝了一口酒。']
    ], { cond: s => hasKid(s) })

  add('buyout', 6, 46, '买断工龄',
    '你四十六岁，厂里改制，可以买断，一年工龄两万。你干了二十二年。',
    [
      ['买断，拿四十四万走人', { money: 4, amb: 4, happy: -3, family: 2 }, '你拿了钱，开了个小店。生意一般，但那笔钱让你撑过了三年。'],
      ['不买断，留在厂里', { con: 4, money: 2, happy: -2 }, '你留下了。厂子后来越来越不景气，你在那儿干到五十五岁内退。'],
      ['买断，但跟人合伙干', { cha: 6, amb: 6, money: 2, happy: 3 }, '你和两个老同事一起开了个加工厂。前两年赔，第三年开始赚。']
    ])

