      ['消极对抗，凡事推', { happy: -2, amb: -4, money: -2 }, '你混了两年，被调到闲职。工资没变，但你每天上班像上坟。'],
      ['主动申请去做专家岗', { int: 5, cha: 4, happy: 4 }, '你转成了技术专家，不管人。你说这才是我该待的位置。']
