      ['不去，让他们自己想办法', { family: -5, happy: 3, amb: 3 }, '你说我也要过自己的日子。孩子请了保姆。你们的关系冷了一阵。'],
      ['去半年，然后回来', { cha: 5, family: 5, happy: 4 }, '你去了半年，把孩子带到能上幼儿园就回来了。你说这样最好。']
