      ['卖了，换一套', { money: 4, family: -3, happy: 2 }, '你卖了，在同一个区换了套小的，还剩了一笔钱。孩子换了学校，适应了半年。'],
      ['不卖，孩子要紧', { family: 5, money: -2, happy: 3 }, '你没卖。三年后房价跌了，你也不知道算不算亏。'],
      ['卖了，租在这片', { int: 5, money: 3, happy: 2 }, '你把房租出去，自己在附近租。孩子没换学校，你还多了一笔收入。']
